// AI: below section was generated by an AI
// Host-side check of the Apollo M-1 boot signpost in wled00/wled.cpp beginStrip() (DECISIONS D23/D24/D27).
// Runs with `npm test` (node --test). It reads the signpost condition from the C++ source and the signpost
// presets from [env:apollo_m1], evaluates the condition for each boot case, and asserts:
//  - a factory-fresh unit with no WiFi (factory def.ps, no def.psc) still boots the signpost playlist,
//  - a no-WiFi owner's launch preset is honoured once chosen (Apollo Dog included) or when it is not the factory one,
//  - WiFi-configured units boot their own preset exactly as upstream,
//  - the signpost is compiled in only where [env:apollo_m1] enables it, and the values match apollo/fs,
//  - every code path that writes bootPreset from the UI also sets bootPresetChosen, and cfg.cpp persists it.
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const read = f => fs.readFileSync(path.join(root, f), 'utf8');
const stripIniComments = s => s.split('\n').map(l => l.replace(/;.*$/, '')).join('\n');

// [env:apollo_m1] build flags (section runs to the next [section] or end of file)
const ini = read('platformio.ini');
const envStart = ini.indexOf('[env:apollo_m1]');
assert.ok(envStart >= 0, '[env:apollo_m1] not found in platformio.ini');
const envEnd = ini.indexOf('\n[', envStart + 1);
const envM1 = stripIniComments(ini.slice(envStart, envEnd < 0 ? undefined : envEnd));
const flag = name => { const m = envM1.match(new RegExp(`-D\\s*${name}=(\\d+)`)); return m ? +m[1] : undefined; };
const SIGNPOST = flag('FACTORY_SIGNPOST_PRESET');
const FACTORY_BOOT = flag('FACTORY_BOOT_PRESET');

// beginStrip() body and the signpost condition inside its #ifdef
const wledCpp = read('wled00/wled.cpp');
const bsStart = wledCpp.indexOf('void WLED::beginStrip()');
const beginStrip = wledCpp.slice(bsStart, wledCpp.indexOf('\nvoid WLED::', bsStart + 1));
const gated = beginStrip.match(/#ifdef FACTORY_SIGNPOST_PRESET([\s\S]*?)#endif/);
// if (<cond>) { String x; if (getPresetName(FACTORY_SIGNPOST_PRESET, x)) bootPs = FACTORY_SIGNPOST_PRESET; }
const condMatch = gated && gated[1].match(/if \(([^;{}]*?)\)\s*\{\s*String (\w+);\s*if \(getPresetName\(FACTORY_SIGNPOST_PRESET, \2\)\)\s*bootPs\s*=\s*FACTORY_SIGNPOST_PRESET;\s*\}/);

// boot decision as compiled for the M-1: returns the preset applied, or 'DEFAULT_COLOR' when none.
// signpostExists models getPresetName(9): false when presets.json has no named preset 9 (e.g. a WLED-MM upgrade).
function bootM1(wifiConfigured, chosen, bootPreset, signpostExists = true) {
  const cond = condMatch[1];
  const ids = new Set(cond.match(/[A-Za-z_]\w*/g));
  const allowed = ['WLED_WIFI_CONFIGURED', 'bootPresetChosen', 'bootPreset', 'FACTORY_BOOT_PRESET', 'FACTORY_SIGNPOST_PRESET'];
  assert.ok([...ids].every(id => allowed.includes(id)), `unexpected identifier in signpost condition: ${cond}`);
  assert.match(cond, /^[\s!&|=()\w]+$/, `signpost condition is not a plain boolean expression: ${cond}`);
  const fn = new Function(...allowed, `return (${cond});`);
  const ps = (fn(wifiConfigured, chosen, bootPreset, FACTORY_BOOT, SIGNPOST) && signpostExists) ? SIGNPOST : bootPreset;
  return ps > 0 ? ps : 'DEFAULT_COLOR';
}

test('signpost is compiled in only by [env:apollo_m1]', () => {
  assert.strictEqual(SIGNPOST, 9, '-D FACTORY_SIGNPOST_PRESET missing from [env:apollo_m1]');
  assert.strictEqual(FACTORY_BOOT, 4, '-D FACTORY_BOOT_PRESET missing from [env:apollo_m1]');
  const elsewhere = stripIniComments(ini.slice(0, envStart)).match(/FACTORY_SIGNPOST_PRESET/g);
  assert.strictEqual(elsewhere, null, 'another env defines FACTORY_SIGNPOST_PRESET');
  for (const f of ['wled00/const.h', 'wled00/wled.h']) {
    assert.doesNotMatch(read(f), /#define\s+FACTORY_SIGNPOST_PRESET/, `${f} must not define a default`);
  }
  assert.ok(condMatch, 'signpost condition not found inside #ifdef FACTORY_SIGNPOST_PRESET in beginStrip()');
  assert.match(beginStrip, /byte bootPs = bootPreset;/);
  assert.match(beginStrip, /if \(bootPs > 0\) \{\s*applyPreset\(bootPs, CALL_MODE_INIT\);/);
  assert.doesNotMatch(beginStrip.replace(gated[0], ''), /FACTORY_SIGNPOST_PRESET|bootPresetChosen/, 'signpost code outside the #ifdef');
});

test('flag values match the factory filesystem', () => {
  const cfg = JSON.parse(read('apollo/fs/cfg.json'));
  const presets = JSON.parse(read('apollo/fs/presets.json'));
  assert.strictEqual(cfg.def.ps, FACTORY_BOOT, 'FACTORY_BOOT_PRESET must equal apollo/fs/cfg.json def.ps');
  assert.strictEqual(cfg.def.psc, undefined, 'factory cfg.json must not mark the boot preset as chosen');
  assert.strictEqual(presets[FACTORY_BOOT].seg[0].n, 'apollo_dog.gif');
  const pl = presets[SIGNPOST].playlist;
  assert.ok(pl, `preset ${SIGNPOST} must be the signpost playlist`);
  assert.deepStrictEqual(pl.ps, [FACTORY_BOOT]);
  assert.strictEqual(presets[pl.end].seg[0].n, 'setup.gif', 'signpost playlist must end on the Setup card');
});

test('boot behaviour per case', () => {
  const D = FACTORY_BOOT;
  // [wifiConfigured, bootPresetChosen, bootPreset, expected, case]
  const cases = [
    [false, false, D, SIGNPOST, 'factory-fresh, no WiFi: dog then setup card'],
    [false, false, 3, 3, 'no WiFi, launch preset 3 (also b8 units updated by OTA, no psc key)'],
    [false, true, 3, 3, 'no WiFi, owner chose 3'],
    [false, true, D, D, 'no WiFi, owner chose Apollo Dog'],
    [false, true, 0, 'DEFAULT_COLOR', 'no WiFi, owner chose none'],
    [false, true, SIGNPOST, SIGNPOST, 'no WiFi, owner chose First Boot on purpose'],
    [false, false, 0, 'DEFAULT_COLOR', 'wiped filesystem: Apollo blue, no missing-preset error'],
    [false, false, 23, 23, 'WLED-MM upgrade, no WiFi, own boot preset'],
    [true, false, D, D, 'WiFi configured: factory dog (D24 self-correction)'],
    [true, false, 0, 'DEFAULT_COLOR', 'WiFi configured, no boot preset'],
    [true, true, 7, 7, 'WiFi configured, owner preset'],
  ];
  for (const [wifi, chosen, bp, want, name] of cases) assert.strictEqual(bootM1(wifi, chosen, bp), want, name);
  // no named preset 9 in presets.json (WLED-MM upgrade, or the owner deleted it): the owner's preset 4 runs
  assert.strictEqual(bootM1(false, false, D, false), D, 'no preset 9: launch preset 4 runs instead of a missing preset');
});

test('every UI write of bootPreset marks it chosen, and cfg.cpp persists the flag', () => {
  for (const f of ['wled00/set.cpp', 'wled00/presets.cpp', 'wled00/json.cpp']) {
    const lines = read(f).split('\n');
    lines.forEach((l, i) => {
      if (!/\bbootPreset\s*=[^=]/.test(l)) return;
      const around = lines.slice(Math.max(0, i - 4), i + 4).join('\n'); // the guard may sit just before or just after the write
      assert.match(around, /#ifdef FACTORY_SIGNPOST_PRESET\s*\n[^\n]*bootPresetChosen = true;/, `${f}:${i + 1} writes bootPreset without setting bootPresetChosen`);
    });
  }
  // LED & Hardware save counts only without WiFi; "Apply at boot" counts only when it picks a different preset
  // (the box is pre-ticked on the current boot preset, so re-saving the dog preset must not end the signpost)
  assert.match(read('wled00/set.cpp'), /if \(!WLED_WIFI_CONFIGURED\) bootPresetChosen = true;/);
  assert.match(read('wled00/presets.cpp'), /if \(\(sObj\[FPSTR\(bootPS\)\] \| bootPreset\) != bootPreset\) bootPresetChosen = true;/);
  const cfg = read('wled00/cfg.cpp');
  assert.match(cfg, /CJSON\(bootPreset, def\["ps"\]\);\s*#ifdef FACTORY_SIGNPOST_PRESET\s*CJSON\(bootPresetChosen, def\["psc"\]\);/);
  assert.match(cfg, /def\["ps"\] = bootPreset;\s*#ifdef FACTORY_SIGNPOST_PRESET\s*def\["psc"\] = bootPresetChosen;/);
  assert.match(read('wled00/wled.h'), /#ifdef FACTORY_SIGNPOST_PRESET\s*WLED_GLOBAL bool bootPresetChosen _INIT\(false\);/);
});
